import { Grid } from "antd";
import Posts from "./components/center/posts/Posts";
import { useState, useEffect } from "react";
import Reels from "./components/center/reels/Reels";
import MainLayout from "./components/layout/MainLayout";

const { useBreakpoint } = Grid;

const Index = () => {
  const screens = useBreakpoint();
  const [activeTab, setActiveTab] = useState(() => {
    return localStorage.getItem("activeTab") || "1";
  });

  const [searchTerm, setSearchTerm] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");

  useEffect(() => {
    const debounced = setTimeout(() => {
      setDebouncedSearch(searchTerm);
    }, 500);

    return () => clearTimeout(debounced);
  }, [searchTerm]);

  useEffect(() => {
    localStorage.setItem("activeTab", activeTab);
  }, [activeTab]);

  useEffect(() => {
    const handleStorageChange = (e) => {
      if (e.key === "activeTab" && e.newValue) {
        setActiveTab(e.newValue);
      }
    };

    window.addEventListener("storage", handleStorageChange);

    return () => {
      window.removeEventListener("storage", handleStorageChange);
    };
  }, []);

  const handleTabChange = (key) => {
    setActiveTab(key);
  };

  return (
    <MainLayout
      activeTab={activeTab}
      onTabChange={handleTabChange}
      searchTerm={searchTerm}
      setSearchTerm={setSearchTerm}
    >
      <div
        style={{
          maxWidth: 800,
          width: "100%",
        }}
      >
        {activeTab === "1" ? (
          <Posts searchTerm={debouncedSearch} />
        ) : (
          <Reels searchTerm={debouncedSearch} />
        )}
      </div>
    </MainLayout>
  );
};

export default Index;
